# Created by OpenAI
"""q_b_proj of a block-fp8 MLA (GLM-5.3 FP8, TP8: 2048 -> 2048) in decode, verify and draft on
gfx950: fp8 activations at 1 x 128 scales times aiter's 16 x 16 shuffled fp8 weight at 128 x 128
scales, bf16 out. A program owns a panel of rows and 8 or 16 output columns and splits K over
its waves in one batched MFMA; the panels' K partials are scaled, summed and exchanged through
LDS. The row panel of a tuned profile tiles the call's rows."""

from typing import NamedTuple
from triton.experimental import gluon
from triton.experimental.gluon import language as gl

class _Panels(NamedTuple):
    count: int = 4
    column_bits: int = 0
    interleaved: bool = False
    native_rows: bool = False

class _Profile(NamedTuple):
    rows: int
    cols: int = 8
    waves: int = 4
    panels: _Panels = _Panels()
    activation: tuple = (1, 16, 4)
    k_width: int = 16
    x_load: str = 'buffer'
    w_load: str = 'slab'
    scales: tuple = (True, True)
    scale_base: str = 'multiply'
    scale_indexing: str = 'packed'
    exchange: str = 'plain'
    shared_order: tuple = (0, 2, 1)
    column_lanes: int = 16
    strips: int = 4
    waves_per_eu: int = 0
    walk: int = 0
    rotation: int = 0
    store: str = 'offset'
    prefetch_scales: bool = False
    early_conversion: bool = False
    flat_grid: bool = False
_PROFILES = {1: _Profile(1, activation=(1, 4, 8), x_load='global', w_load='global', scale_base='divide', exchange='reserved', shared_order=(1, 0, 2), column_lanes=8, walk=123, store='base'), 2: _Profile(2, activation=(1, 4, 8), x_load='rebased', w_load='buffer', scales=(False, False), exchange='reserved', column_lanes=8, walk=123), 4: _Profile(4, panels=_Panels(4, 1, True), x_load='factored', scales=(True, False), waves_per_eu=4, walk=123, store='merged'), 8: _Profile(4, cols=16, panels=_Panels(4, 2), activation=(1, 32, 4), k_width=32, w_load='buffer', scales=(False, False), exchange='xor', strips=8, waves_per_eu=4, rotation=48), 16: _Profile(8, cols=16, waves=8, panels=_Panels(2, 0, True, True), activation=(2, 16, 8), k_width=32, x_load='combined', w_load='reverse', scales=(False, False), exchange='compact', shared_order=(2, 0, 1), waves_per_eu=6, store='merged', prefetch_scales=True, early_conversion=True, flat_grid=True, scale_indexing='panel')}

@gluon.constexpr_function
def _axis_layout(axis, layout):
    for dim in range(layout.rank - 1, -1, -1):
        if dim != axis:
            layout = gl.SliceLayout(dim, layout)
    return layout

@gluon.jit
def _axis(size: gl.constexpr, axis: gl.constexpr, layout: gl.constexpr):
    RANK: gl.constexpr = layout.rank
    index = gl.arange(0, size, _axis_layout(axis, layout))
    for dim in gl.static_range(0, RANK):
        if dim != axis:
            index = gl.expand_dims(index, dim)
    return index

@gluon.jit
def _group(batch, panel, batches: gl.constexpr, P: gl.constexpr):
    if P.interleaved:
        return batch + panel * batches
    return batch * P.count + panel

@gluon.jit
def _load(ptr, offset, buffered: gl.constexpr):
    if buffered:
        return gl.amd.cdna4.buffer_load(ptr, offset)
    return gl.load(ptr + offset)

@gluon.jit
def _operands(X, W, first_m, tile, K: gl.constexpr, XM: gl.constexpr, XK: gl.constexpr, C: gl.constexpr, mma: gl.constexpr):
    P: gl.constexpr = C.panels
    S: gl.constexpr = K // (128 * P.count)
    al: gl.constexpr = gl.BlockedLayout([1, C.activation[0], C.activation[1]], [1, 64 // C.activation[2], C.activation[2]], [C.waves, 1, 1], [2, 1, 0])
    if C.k_width == 32:
        bl: gl.constexpr = gl.DotOperandLayout(1, mma, C.k_width)
    else:
        bl: gl.constexpr = gl.BlockedLayout([1, 16, 1], [1, 4, 16], [C.waves, 1, 1], [2, 1, 0])
    batch, row, k = (_axis(S, 0, al), _axis(C.rows * P.count, 1, al), _axis(128, 2, al))
    group = _group(batch, row % P.count, S, P)
    if C.x_load == 'rebased':
        base = X + (first_m * XM + batch * P.count * 128 * XK)
        offset = row // P.count * XM + (row % P.count * 128 + k) * XK
        a = gl.load(base + offset)
    elif C.x_load == 'factored':
        a = _load(X + first_m * XM, row // P.count * XM + group * (128 * XK) + k * XK, True)
    elif C.x_load == 'combined':
        a = _load(X, (first_m + row // P.count) * XM + (group * 128 + k) * XK, False)
    else:
        a = _load(X + first_m * XM, row // P.count * XM + (group * 128 + k) * XK, C.x_load == 'buffer')
    if C.early_conversion:
        a = gl.convert_layout(a, gl.DotOperandLayout(0, mma, C.k_width))
    batch, k, col = (_axis(S, 0, bl), _axis(128, 1, bl), _axis(C.cols * P.count, 2, bl))
    group = _group(batch, col // C.cols, S, P)
    n = tile * C.cols % 16 + col % C.cols
    if C.w_load == 'reverse':
        offsets = k % 16 + n * 16 + k // 16 * 256 + group * 2048
        base = W + tile // (16 // C.cols) * (K * 16)
    elif C.w_load == 'slab':
        offsets = group * 2048 + k // 16 * 256 + n * 16 + k % 16
        base = W + tile * C.cols // 16 * K * 16
    else:
        kk = group * 128 + k
        offsets = kk // 16 * 256 + n * 16 + kk % 16
        base = W + tile * C.cols // 16 * K * 16
    b = _load(base, offsets, C.w_load != 'global')
    return (gl.convert_layout(a, gl.DotOperandLayout(0, mma, C.k_width)), gl.convert_layout(b, gl.DotOperandLayout(1, mma, C.k_width)))

@gluon.jit
def _select_half(dot, BIT: gl.constexpr, BN: gl.constexpr, columns: gl.constexpr):
    S: gl.constexpr = dot.shape[0]
    R: gl.constexpr = dot.shape[1]
    N: gl.constexpr = dot.shape[2]
    if columns:
        lo = gl.amd.slice(dot, (S, R, N // 2), (0, 0, 0))
        hi = gl.amd.slice(dot, (S, R, N // 2), (0, 0, N // 2))
        take_lo = _axis(R, 1, lo.type.layout) & BIT == 0
    else:
        lo, hi = gl.split(gl.permute(gl.reshape(dot, (S, R // 2, 2, N)), (0, 1, 3, 2)))
        column = _axis(N, 2, lo.type.layout)
        if N == 2 * BN and BIT == 1:
            return gl.where(column >= BN, hi, lo)
        if N == 2 * BN * BIT:
            take_lo = column < BN * BIT
        else:
            take_lo = column // BN & BIT == 0
    return gl.where(take_lo, lo, hi)

@gluon.jit
def _diagonal(dot, C: gl.constexpr):
    P: gl.constexpr = C.panels
    S: gl.constexpr = dot.shape[0]
    BITS: gl.constexpr = P.count.bit_length() - 1
    RB: gl.constexpr = BITS - P.column_bits
    selected = dot
    for bit in gl.static_range(BITS - 1, RB - 1, -1):
        selected = _select_half(selected, 1 << bit, C.cols, True)
    if RB > 0:
        if P.column_bits == 0 and (not P.native_rows):
            rl: gl.constexpr = gl.BlockedLayout([1, P.count, 1], [1, 4, 16], [C.waves, 1, 1], [2, 1, 0])
        else:
            rl: gl.constexpr = dot.type.layout
        selected = gl.convert_layout(selected, rl)
        for bit in gl.static_range(0, RB):
            selected = _select_half(selected, 1 << bit, C.cols, False)
    H: gl.constexpr = P.count if P.column_bits == 0 else 1 << P.column_bits
    L: gl.constexpr = P.count // H
    return gl.reshape(selected, (S, C.rows, H, L * C.cols))

@gluon.jit
def _scales(view, XS, WS, first_m, tile, XSM: gl.constexpr, XSK: gl.constexpr, WSN: gl.constexpr, WSK: gl.constexpr, C: gl.constexpr):
    P: gl.constexpr = C.panels
    S: gl.constexpr = view.shape[0]
    H: gl.constexpr = view.shape[2]
    L: gl.constexpr = P.count // H
    if C.scale_indexing == 'packed':
        index_view = gl.reshape(view, (S, C.rows * H, L * C.cols))
        ul: gl.constexpr = index_view.type.layout
        row_panel = _axis(C.rows * H, 1, ul)
        row, panel = (row_panel // H, row_panel % H * L)
        COL_AXIS: gl.constexpr = 2
    else:
        ul: gl.constexpr = view.type.layout
        row, panel = (_axis(C.rows, 1, ul), _axis(H, 2, ul) * L)
        COL_AXIS: gl.constexpr = 3
    batch = _axis(S, 0, ul)
    if L > 1:
        panel = panel + _axis(L * C.cols, COL_AXIS, ul) // C.cols
    group = _group(batch, panel, S, P)
    if C.scales[0]:
        sa = gl.amd.cdna4.buffer_load(XS + first_m * XSM, row * XSM + group * XSK)
    else:
        sa = gl.load(XS + (first_m + row) * XSM + group * XSK)
    if C.scale_base == 'divide':
        base = WS + tile // (128 // C.cols) * WSN
    else:
        base = WS + tile * C.cols // 128 * WSN
    wo = group * WSK
    if C.scale_indexing == 'packed' and P.column_bits == 0:
        wo = wo + gl.full((1, 1, C.cols), 0, gl.int32, ul)
    sw = _load(base, wo, C.scales[1])
    return (sa, sw)

@gluon.jit
def _fold(view, sa, sw, C: gl.constexpr):
    S: gl.constexpr = view.shape[0]
    H: gl.constexpr = view.shape[2]
    L: gl.constexpr = view.shape[3] // C.cols
    if C.scale_indexing == 'packed':
        view = gl.reshape(view, (S, C.rows * H, L * C.cols))
    scaled = view * sa * sw
    folded = gl.sum(gl.reshape(scaled, (S, C.rows, H, L * C.cols)), 2)
    return gl.sum(gl.reshape(folded, (S, C.rows, L, C.cols)), 2)

@gluon.jit
def _readout(partial, Y, first_m, tile, N: gl.constexpr, C: gl.constexpr, reserved):
    shared: gl.constexpr = gl.SwizzledSharedLayout(1, 1, 1, C.shared_order)
    if C.exchange == 'compact':
        compact: gl.constexpr = gl.SharedLinearLayout(((1, 0, 0), (2, 0, 0), (0, 0, 1), (0, 0, 2), (0, 0, 4), (0, 0, 8), (0, 1, 0), (0, 2, 0), (0, 4, 0), (4, 0, 0)))
        smem = gl.allocate_shared_memory(gl.float32, partial.shape, compact)
        group = _axis(partial.shape[0], 0, partial.type.layout)
        row = _axis(C.rows, 1, partial.type.layout)
        smem.scatter(partial, group ^ row >> 1 & 3, 0)
        reader: gl.constexpr = gl.BlockedLayout([2, 1, 1], [1, 4, 16], [1, C.waves, 1], [0, 2, 1])
    else:
        if C.exchange == 'reserved':
            smem = reserved
            smem.store(partial)
        elif C.exchange == 'xor':
            smem = gl.allocate_shared_memory(gl.float32, partial.shape, shared)
            group = _axis(partial.shape[0], 0, partial.type.layout)
            row = _axis(C.rows, 1, partial.type.layout)
            smem.scatter(partial, group ^ row & partial.shape[0] - 1, 0)
        else:
            smem = gl.allocate_shared_memory(gl.float32, partial.shape, shared, partial)
        reader: gl.constexpr = gl.BlockedLayout([1, 1, 1], [1, 64 // C.column_lanes, C.column_lanes], [1, C.waves, 1], [2, 1, 0])
    value = gl.sum(smem.load(reader), 0)
    ol: gl.constexpr = value.type.layout
    row = first_m + gl.arange(0, C.rows, gl.SliceLayout(1, ol))
    col = tile * C.cols + gl.arange(0, C.cols, gl.SliceLayout(0, ol))
    if C.store == 'base':
        gl.store(Y + first_m * N + tile * C.cols + gl.arange(0, C.rows, gl.SliceLayout(1, ol))[:, None] * N + gl.arange(0, C.cols, gl.SliceLayout(0, ol))[None, :], value.to(gl.bfloat16), cache_modifier='.wt')
    elif C.store == 'merged':
        gl.store(Y + (row[:, None] * N + col[None, :]), value.to(gl.bfloat16), cache_modifier='.wt')
    else:
        gl.store(Y + row[:, None] * N + col[None, :], value.to(gl.bfloat16), cache_modifier='.wt')

@gluon.jit
def _decode_gemm(X, XS, W, WS, Y, M: gl.constexpr, N: gl.constexpr, K: gl.constexpr, XM: gl.constexpr, XK: gl.constexpr, XSM: gl.constexpr, XSK: gl.constexpr, WSN: gl.constexpr, WSK: gl.constexpr, C: gl.constexpr):
    P: gl.constexpr = C.panels
    S: gl.constexpr = K // (128 * P.count)
    gl.static_assert(K % (128 * P.count) == 0 and M % C.rows == 0)
    gl.static_assert(N % C.cols == 0 and N // C.cols % C.strips == 0)
    gl.static_assert(P.count > 0 and P.count & P.count - 1 == 0)
    gl.static_assert(P.column_bits >= 0 and P.column_bits < P.count.bit_length())
    gl.static_assert(C.cols <= 16 and 16 % C.cols == 0)
    gl.static_assert(P.column_bits == 0 or C.cols * (P.count >> P.column_bits) % 16 == 0)
    tile = gl.program_id(0).to(gl.uint32)
    if C.flat_grid:
        first_m = tile // (N // C.cols) * C.rows
        tile = tile % (N // C.cols)
        tile = tile % C.strips * (N // C.cols // C.strips) + tile // C.strips
    else:
        first_m = 0 if M == C.rows else gl.program_id(1).to(gl.uint32) * C.rows
        if C.walk != 0 and N == 2048 and (K == 2048):
            gl.static_assert(C.walk & 1 == 1)
            tile = tile * C.walk % (N // C.cols)
        else:
            tile = tile % C.strips * (N // C.cols // C.strips) + tile // C.strips
    if C.rotation != 0 and N == 2048 and (K == 2048):
        tile = (tile + C.rotation) % (N // C.cols)
    if C.exchange == 'reserved':
        reserved = gl.allocate_shared_memory(gl.float32, (S, C.rows, C.cols), gl.SwizzledSharedLayout(1, 1, 1, C.shared_order))
    else:
        reserved = None
    mma: gl.constexpr = gl.amd.AMDMFMALayout(4, [16, 16, 32], False, [C.waves, 1, 1])
    if C.prefetch_scales:
        template = _diagonal(gl.zeros((S, C.rows * P.count, C.cols * P.count), gl.float32, mma), C)
    a, b = _operands(X, W, first_m, tile, K, XM, XK, C, mma)
    if C.prefetch_scales:
        sa, sw = _scales(template, XS, WS, first_m, tile, XSM, XSK, WSN, WSK, C)
    dot = gl.amd.cdna4.mfma(a, b, gl.zeros((S, C.rows * P.count, C.cols * P.count), gl.float32, mma))
    view = _diagonal(dot, C)
    if not C.prefetch_scales:
        sa, sw = _scales(view, XS, WS, first_m, tile, XSM, XSK, WSN, WSK, C)
    _readout(_fold(view, sa, sw, C), Y, first_m, tile, N, C, reserved)


def _profile(m):
    """The tuned profile (keyed by the row count it was tuned at) whose row panel tiles m rows."""
    if m in (1, 2, 4, 8, 16):
        return _PROFILES[m]
    if m % 8 == 0:
        return _PROFILES[16]
    if m % 4 == 0:
        return _PROFILES[8]
    return _PROFILES[2] if m % 2 == 0 else _PROFILES[1]


def run(*, a, b, a_scale, b_scale, scale_major_mode, trans_b, operand_format, bias, out_dtype, out):
    """out = (a * a_scale) @ (b * b_scale).T in bf16; a_scale holds its (m, k / 128) values column
    by column, as aiter's preshuffled GEMM reads them."""
    m, k = a.shape
    n = b.shape[0]
    assert (n, k) == (2048, 2048) and a.stride() == (k, 1) and b_scale.stride() == (k // 128, 1)
    profile = _profile(m)
    tiles = n // profile.cols
    grid = (tiles * (m // profile.rows),) if profile.flat_grid else (tiles, m // profile.rows)
    common = (m, n, k, k, 1, 1, m, k // 128, 1)
    _decode_gemm[grid](a, a_scale, b, b_scale, out, *common, profile, num_warps=profile.waves, waves_per_eu=profile.waves_per_eu)
